const items = $input.first().json;
const arr = Array.isArray(items) ? items : [items];
return arr.map(d => ({ json: d }));

const resp = $input.first().json;
const d = Array.isArray(resp) ? resp : [resp];
// El nodo anterior ya entrega un item por dealer (ver 'Un item por dealer').
const dealer = $json;
if (!dealer || !dealer.trial_ends_at) return [];

const finTrial = new Date(dealer.trial_ends_at);
const hoy = new Date();
const diasRestantes = Math.ceil((finTrial.getTime() - hoy.getTime()) / 86400000);
const diasTranscurridos = 30 - diasRestantes;

let objetivo = 0;
if (diasTranscurridos >= 28) objetivo = 4;
else if (diasTranscurridos >= 21) objetivo = 3;
else if (diasTranscurridos >= 10) objetivo = 2;
else if (diasTranscurridos >= 3) objetivo = 1;

const etapaActual = parseInt(dealer.trial_email_stage || 0) || 0;
if (objetivo <= etapaActual) return [];

return [{ json: {
  dealerId: dealer.id,
  nombre: dealer.name,
  slug: dealer.slug,
  email: dealer.email,
  plan: dealer.subscription_plan,
  etapa: objetivo,
  diasRestantes: diasRestantes,
  finTrial: dealer.trial_ends_at
} }];

const items = $('Calcular etapa').all();
const statsItems = $input.all();
const MAIL_FROM = 'Black Label Market <hola@blacklabelmarket.es>';
const PERFIL_BASE = 'https://blacklabelmarket.es/dealers/';
const SUSCRIPCION = 'https://blacklabelmarket.es/dashboard/suscripcion';

function nf(n) { return new Intl.NumberFormat('es-ES').format(n || 0); }

const salida = [];
for (let i = 0; i < items.length; i++) {
  const e = items[i].json;
  if (!e.email || e.email.indexOf('@') < 1) continue;

  const stats = statsItems[i] ? statsItems[i].json : { vistas: 0, leads: 0, vehiculosActivos: 0 };
  const perfilUrl = PERFIL_BASE + e.slug;
  let subject, html;

  if (e.etapa === 1) {
    subject = e.nombre + ', ¿qué tal las primeras impresiones de Black Label Market?';
    html = '<p>Buenas,</p>' +
      '<p>Llevas unos días con vuestro perfil ya publicado (<a href="' + perfilUrl + '">' + perfilUrl + '</a>). Si os falta terminar de completar el perfil o subir stock, es el momento — cuanto antes esté todo, antes empiezan a llegar contactos.</p>' +
      '<p>Cualquier duda sobre cómo funciona el panel, respondednos a este correo.</p>' +
      '<p>Un saludo,<br>Black Label Market</p>';
  } else if (e.etapa === 2) {
    subject = 'Sacadle partido a vuestro plan ' + (e.plan || '') + ' en Black Label Market';
    html = '<p>Buenas,</p>' +
      '<p>Con stock publicado, dos cosas que suelen marcar la diferencia: mantener las fichas con fotos y precio actualizados, y usar los <strong>boosts</strong> para destacar el vehículo que más queréis mover esta semana.</p>' +
      '<p>Vuestro panel: <a href="https://blacklabelmarket.es/dashboard">blacklabelmarket.es/dashboard</a></p>' +
      '<p>Un saludo,<br>Black Label Market</p>';
  } else if (e.etapa === 3) {
    subject = 'Vuestra prueba en Black Label Market termina en ' + e.diasRestantes + ' días';
    html = '<p>Buenas,</p>' +
      '<p>Quedan ' + e.diasRestantes + ' días de prueba. Hasta ahora, vuestro perfil ha tenido <strong>' + nf(stats.vistas) + ' visitas</strong> y habéis recibido <strong>' + nf(stats.leads) + ' contactos</strong> a través del market.</p>' +
      '<p>Para que el perfil siga activo sin interrupción, podéis elegir vuestro plan cuando queráis, sin esperar al último día: <a href="' + SUSCRIPCION + '">' + SUSCRIPCION + '</a></p>' +
      '<p>Un saludo,<br>Black Label Market</p>';
  } else {
    subject = 'Vuestra prueba en Black Label Market termina en ' + Math.max(e.diasRestantes, 0) + ' días';
    html = '<p>Buenas,</p>' +
      '<p>Resumen de vuestro periodo de prueba: <strong>' + nf(stats.vistas) + ' visitas</strong> al perfil, <strong>' + nf(stats.leads) + ' contactos</strong> recibidos, <strong>' + nf(stats.vehiculosActivos) + ' vehículos</strong> activos publicados.</p>' +
      '<p>Para que vuestro perfil y stock sigan visibles sin interrupción, elegid vuestro plan aquí: <a href="' + SUSCRIPCION + '">' + SUSCRIPCION + '</a></p>' +
      '<p>Si necesitáis más tiempo o tenéis dudas sobre qué plan os encaja, respondednos a este correo — lo hablamos.</p>' +
      '<p>Un saludo,<br>Black Label Market</p>';
  }

  salida.push({ json: {
    dealerId: e.dealerId, etapa: e.etapa, nombre: e.nombre,
    email: e.email, emailFrom: MAIL_FROM, emailSubject: subject, emailHtml: html
  } });
}
return salida;

const items = $('Componer email').all().map(i => i.json);
if (!items.length) return [];
const porEtapa = { 1: 'día 3 (check-in)', 2: 'día 10 (aprovechar plan)', 3: 'día 21 (recordatorio)', 4: 'día 28 (conversión + resumen)' };
const lineas = items.map(e => '- ' + e.nombre + ': etapa ' + porEtapa[e.etapa]);
return [{ json: { slackPayload: { text: '*Trial drip enviado hoy: ' + items.length + '*\n' + lineas.join('\n') } } }];
